const insertMigrationItems = `-- name: InsertMigrationItems :execrows
INSERT INTO migration_items (workspace_id, migration_id, source_id, folder_id, thread_key, dedupe_key, received_at, size_bytes,
    meta, state, reason, in_copy)
SELECT $1, $2, unnest($3::text[]), unnest($4::int[]), unnest($5::text[]),
    unnest($5::text[]), unnest($6::timestamptz[]), unnest($7::bigint[]), unnest($8::jsonb[]),
    $9, $10, $11
ON CONFLICT (workspace_id, migration_id, source_id) DO NOTHING
`

type InsertMigrationItemsParams struct {
	WorkspaceID uuid.UUID
	MigrationID uuid.UUID
	SourceIds   []string
	FolderIds   []int32
	DedupeKeys  []string
	ReceivedAts []time.Time
	Sizes       []int64
	Metas       [][]byte
	State       string
	Reason      string
	InCopy      bool
}

func (q *Queries) InsertMigrationItems(ctx context.Context, arg InsertMigrationItemsParams) (int64, error) {
	result, err := q.db.Exec(ctx, insertMigrationItems,
		arg.WorkspaceID,
		arg.MigrationID,
		arg.SourceIds,
		arg.FolderIds,
		arg.DedupeKeys,
		arg.ReceivedAts,
		arg.Sizes,
		arg.Metas,
		arg.State,
		arg.Reason,
		arg.InCopy,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const insertMigrationPlanNames = `-- name: InsertMigrationPlanNames :exec
INSERT INTO migration_plan_names (workspace_id, migration_id, email, name)
SELECT DISTINCT ON (c.email) $1, $2, c.email, c.name FROM (
    SELECT x.a->>'email' AS email, x.a->>'name' AS name, count(*) AS n
    FROM migration_items i
    CROSS JOIN LATERAL (
        SELECT i.meta->'from' AS a
        UNION ALL SELECT jsonb_array_elements(coalesce(i.meta->'to', '[]'::jsonb))
        UNION ALL SELECT jsonb_array_elements(coalesce(i.meta->'cc', '[]'::jsonb))
    ) x
    WHERE i.workspace_id = $1 AND i.migration_id = $2 AND i.folder_id = ANY($3::int[])
      AND length(coalesce(x.a->>'email', '')) BETWEEN 1 AND 998 AND coalesce(x.a->>'name', '') <> ''
    GROUP BY 1, 2
) c
ORDER BY c.email, c.n DESC, c.name COLLATE "C"
`

type InsertMigrationPlanNamesParams struct {
	WorkspaceID uuid.UUID
	MigrationID uuid.UUID
	FolderIds   []int32
}

func (q *Queries) InsertMigrationPlanNames(ctx context.Context, arg InsertMigrationPlanNamesParams) error {
	_, err := q.db.Exec(ctx, insertMigrationPlanNames, arg.WorkspaceID, arg.MigrationID, arg.FolderIds)
	return err
}

